import{_ as a,c as o,o as r,a3 as t}from"./chunks/framework.Dk6sf0Ip.js";const m=JSON.parse('{"title":"Manual de Usuario - Reporte RHSUELDOS","description":"","frontmatter":{},"headers":[],"relativePath":"reportes/manual_usuario_rhsueldos.md","filePath":"reportes/manual_usuario_rhsueldos.md","lastUpdated":1759238350000}'),s={name:"reportes/manual_usuario_rhsueldos.md"};function l(i,e,n,d,c,p){return r(),o("div",null,e[0]||(e[0]=[t('<h1 id="manual-de-usuario-reporte-rhsueldos" tabindex="-1">Manual de Usuario - Reporte RHSUELDOS <a class="header-anchor" href="#manual-de-usuario-reporte-rhsueldos" aria-label="Permalink to &quot;Manual de Usuario - Reporte RHSUELDOS&quot;">​</a></h1><h2 id="introduccion" tabindex="-1">Introducción <a class="header-anchor" href="#introduccion" aria-label="Permalink to &quot;Introducción&quot;">​</a></h2><p>El reporte <strong>RHSUELDOS</strong> está diseñado para proporcionarle información detallada sobre sueldos y retiros de personal. Este manual le guiará en el uso efectivo del reporte para consultar, filtrar y analizar la información financiera relacionada con pagos a empleados y colaboradores.</p><h2 id="acceso-al-reporte" tabindex="-1">Acceso al Reporte <a class="header-anchor" href="#acceso-al-reporte" aria-label="Permalink to &quot;Acceso al Reporte&quot;">​</a></h2><p>Para acceder al reporte RHSUELDOS:</p><ol><li>Inicie sesión en el sistema con sus credenciales</li><li>Navegue hasta el módulo de Recursos Humanos</li><li>En la sección &quot;Reportes&quot;, seleccione &quot;RHSUELDOS&quot;</li></ol><h2 id="funcionalidades-principales" tabindex="-1">Funcionalidades Principales <a class="header-anchor" href="#funcionalidades-principales" aria-label="Permalink to &quot;Funcionalidades Principales&quot;">​</a></h2><h3 id="_1-visualizacion-de-datos" tabindex="-1">1. Visualización de Datos <a class="header-anchor" href="#_1-visualizacion-de-datos" aria-label="Permalink to &quot;1. Visualización de Datos&quot;">​</a></h3><p>El reporte muestra la siguiente información:</p><ul><li><strong>Fecha</strong>: Día en que se realizó el pago o retiro</li><li><strong>Descripción</strong>: Detalle o motivo del pago</li><li><strong>Rol</strong>: Categoría o función del empleado</li><li><strong>Total</strong>: Monto total con impuestos incluidos</li></ul><p>La información se presenta agrupada por empleado, con totales calculados para cada persona.</p><h3 id="_2-filtros-disponibles" tabindex="-1">2. Filtros Disponibles <a class="header-anchor" href="#_2-filtros-disponibles" aria-label="Permalink to &quot;2. Filtros Disponibles&quot;">​</a></h3><p>El reporte permite filtrar la información mediante los siguientes criterios:</p><table tabindex="0"><thead><tr><th>Filtro</th><th>Descripción</th><th>Ejemplo</th></tr></thead><tbody><tr><td>Fecha Desde</td><td>Fecha inicial del período a consultar</td><td>01/01/2025</td></tr><tr><td>Fecha Hasta</td><td>Fecha final del período a consultar</td><td>30/04/2025</td></tr><tr><td>ID</td><td>Identificador numérico del empleado</td><td>15478</td></tr><tr><td>Nombre</td><td>Nombre completo o parcial del empleado</td><td>&quot;Martínez&quot;</td></tr><tr><td>Rol</td><td>Categoría o función del empleado</td><td>&quot;Gerente&quot;</td></tr></tbody></table><p><strong>Nota</strong>: Si no se especifican fechas, el sistema mostrará por defecto los datos de los últimos 6 meses hasta la fecha actual.</p><h2 id="guia-paso-a-paso" tabindex="-1">Guía Paso a Paso <a class="header-anchor" href="#guia-paso-a-paso" aria-label="Permalink to &quot;Guía Paso a Paso&quot;">​</a></h2><h3 id="generacion-de-un-reporte-basico" tabindex="-1">Generación de un Reporte Básico <a class="header-anchor" href="#generacion-de-un-reporte-basico" aria-label="Permalink to &quot;Generación de un Reporte Básico&quot;">​</a></h3><ol><li>Acceda al reporte RHSUELDOS</li><li>Deje todos los filtros en blanco para ver todos los registros disponibles</li><li>Haga clic en &quot;Generar Reporte&quot;</li><li>El sistema mostrará los datos agrupados por empleado</li></ol><h3 id="filtrado-por-periodo" tabindex="-1">Filtrado por Período <a class="header-anchor" href="#filtrado-por-periodo" aria-label="Permalink to &quot;Filtrado por Período&quot;">​</a></h3><p>Para consultar pagos en un período específico:</p><ol><li>Si ingresa solo una fecha filtrar solo ese dia.</li><li>En el campo &quot;Fecha Desde&quot;, seleccione la fecha inicial</li><li>En el campo &quot;Fecha Hasta&quot;, seleccione la fecha final</li><li>Haga clic en &quot;Generar Reporte&quot;</li><li>Visualice los resultados filtrados por el período seleccionado</li></ol><h3 id="busqueda-por-empleado" tabindex="-1">Búsqueda por Empleado <a class="header-anchor" href="#busqueda-por-empleado" aria-label="Permalink to &quot;Búsqueda por Empleado&quot;">​</a></h3><h4 id="por-id" tabindex="-1">Por Id <a class="header-anchor" href="#por-id" aria-label="Permalink to &quot;Por Id&quot;">​</a></h4><p>Para localizar pagos a un empleado específico:</p><ol><li>En el campo &quot;Id&quot;, elija el empleado, este colocara el id del mismo.</li><li>Haga clic en &quot;Generar Reporte&quot;</li><li>El sistema mostrará solo los registros que coincidan con el nombre especificado</li></ol><h4 id="por-nombre" tabindex="-1">Por Nombre <a class="header-anchor" href="#por-nombre" aria-label="Permalink to &quot;Por Nombre&quot;">​</a></h4><p>Para localizar pagos a un empleado específico:</p><ol><li>En el campo &quot;Nombre&quot;, escriba el nombre completo o parcial del empleado</li><li>Haga clic en &quot;Generar Reporte&quot;</li><li>El sistema mostrará solo los registros que coincidan con el nombre especificado</li></ol><h3 id="filtrado-por-rol" tabindex="-1">Filtrado por Rol <a class="header-anchor" href="#filtrado-por-rol" aria-label="Permalink to &quot;Filtrado por Rol&quot;">​</a></h3><p>Para ver pagos según la función o categoría:</p><ol><li>En el campo &quot;Rol&quot;, escriba la categoría que desea consultar</li><li>Haga clic en &quot;Generar Reporte&quot;</li><li>Visualice los resultados correspondientes a esa categoría</li></ol><h2 id="interpretacion-de-resultados" tabindex="-1">Interpretación de Resultados <a class="header-anchor" href="#interpretacion-de-resultados" aria-label="Permalink to &quot;Interpretación de Resultados&quot;">​</a></h2><h3 id="agrupacion-por-empleado" tabindex="-1">Agrupación por Empleado <a class="header-anchor" href="#agrupacion-por-empleado" aria-label="Permalink to &quot;Agrupación por Empleado&quot;">​</a></h3><p>El reporte organiza la información por nombre de empleado:</p><ul><li>Cada grupo comienza con una barra gris que muestra el nombre del empleado</li><li>A continuación se listan todos los pagos o retiros asociados a ese empleado</li><li>Al final de cada grupo se muestra un total acumulado</li></ul><h3 id="totales-y-subtotales" tabindex="-1">Totales y Subtotales <a class="header-anchor" href="#totales-y-subtotales" aria-label="Permalink to &quot;Totales y Subtotales&quot;">​</a></h3><ul><li><strong>Total por empleado</strong>: Suma de todos los pagos realizados al empleado en el período seleccionado</li><li>Los montos se muestran en formato de moneda con el símbolo &quot;$&quot;</li></ul><h2 id="opciones-de-exportacion" tabindex="-1">Opciones de Exportación <a class="header-anchor" href="#opciones-de-exportacion" aria-label="Permalink to &quot;Opciones de Exportación&quot;">​</a></h2><p>El reporte puede exportarse en varios formatos para su posterior uso:</p><ol><li><strong>PDF</strong>: Ideal para imprimir o compartir el reporte sin modificaciones</li><li><strong>Excel</strong>: Permite realizar análisis adicionales y cálculos sobre los datos</li><li><strong>CSV</strong>: Formato de texto plano compatible con diversas aplicaciones</li></ol><p>Para exportar:</p><ol><li>Genere el reporte con los filtros deseados</li><li>Haga clic en el botón &quot;Exportar&quot; ubicado en la parte superior</li><li>Seleccione el formato deseado</li><li>Especifique la ubicación donde desea guardar el archivo</li></ol><h2 id="🔍-consejos-utiles" tabindex="-1">🔍 Consejos Útiles <a class="header-anchor" href="#🔍-consejos-utiles" aria-label="Permalink to &quot;🔍 Consejos Útiles&quot;">​</a></h2><ul><li><strong>🧩 Filtros combinados</strong>: Puedes usar varios filtros simultáneamente para obtener resultados más específicos.</li><li><strong>🔎 Búsquedas parciales</strong>: El sistema reconoce coincidencias parciales en campos de texto (<em>Nombre</em> y <em>Rol</em>).</li><li><strong>📊 Ordenamiento</strong>: Por defecto, los resultados se ordenan por fecha (⏳ los más antiguos primero).</li><li><strong>🌈 Filas alternadas</strong>: Para facilitar la lectura, las filas se muestran con colores alternados (estilo zebra 🦓).</li></ul><h2 id="solucion-de-problemas-comunes" tabindex="-1">Solución de Problemas Comunes <a class="header-anchor" href="#solucion-de-problemas-comunes" aria-label="Permalink to &quot;Solución de Problemas Comunes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problema</th><th>Posible Causa</th><th>Solución</th></tr></thead><tbody><tr><td>No aparecen resultados</td><td>Filtros demasiado restrictivos</td><td>Amplíe el rango de fechas o elimine algunos filtros</td></tr><tr><td>Faltan empleados</td><td>El empleado no tiene pagos en el período seleccionado</td><td>Verifique y amplíe el rango de fechas</td></tr><tr><td>Totales incorrectos</td><td>Filtros parciales aplicados</td><td>Asegúrese de incluir todo el período relevante</td></tr><tr><td>Error al exportar</td><td>Problema de permisos</td><td>Verifique los permisos de su cuenta o contacte al administrador</td></tr></tbody></table><h2 id="📚-glosario-de-terminos" tabindex="-1">📚 Glosario de Términos <a class="header-anchor" href="#📚-glosario-de-terminos" aria-label="Permalink to &quot;📚 Glosario de Términos&quot;">​</a></h2><ul><li><p><strong>📅 Fecha</strong>: Día en que se registró el pago o retiro<br> ⚠️ <em>Ejemplo: 15/05/2024</em></p></li><li><p><strong>📝 Descripción</strong>: Detalle o concepto del pago realizado<br> ⚠️ <em>Ejemplo: &quot;Compra de materiales de oficina&quot;</em></p></li><li><p><strong>👔 Rol</strong>: Categoría o función asignada al empleado en el sistema<br> � <em>Ejemplo: &quot;Administrador&quot;, &quot;Contador&quot;</em></p></li><li><p><strong>💰 Total</strong>: Monto final que incluye todos los impuestos aplicables<br> 💡 <em>Se muestra en formato moneda (ej: $105,250.00 ARS)</em></p></li></ul><h2 id="❓-preguntas-frecuentes-faq" tabindex="-1">❓ Preguntas Frecuentes (FAQ) <a class="header-anchor" href="#❓-preguntas-frecuentes-faq" aria-label="Permalink to &quot;❓ Preguntas Frecuentes (FAQ)&quot;">​</a></h2><h3 id="🌐-generales" tabindex="-1">🌐 Generales <a class="header-anchor" href="#🌐-generales" aria-label="Permalink to &quot;🌐 Generales&quot;">​</a></h3><p><strong>❔ P: ¿Con qué frecuencia se actualizan los datos del reporte?</strong><br> ✅ <strong>R:</strong> Los datos se actualizan en tiempo real. Cada vez que se genera el reporte, se obtiene la información más reciente disponible en el sistema.</p><p><strong>❔ P: ¿Puedo guardar mis configuraciones de filtros para uso futuro?</strong><br> ⚠️ <strong>R:</strong> Actualmente el sistema no permite guardar configuraciones de filtros. Se recomienda anotar las combinaciones de filtros que utiliza con frecuencia.</p><p><strong>❔ P: ¿El reporte muestra información de años anteriores?</strong><br> ✅ <strong>R:</strong> Sí, el reporte puede mostrar datos históricos siempre que estén disponibles en la base de datos. Solo necesita especificar las fechas correspondientes en los filtros.</p><h3 id="🔍-filtros-y-busqueda" tabindex="-1">🔍 Filtros y Búsqueda <a class="header-anchor" href="#🔍-filtros-y-busqueda" aria-label="Permalink to &quot;🔍 Filtros y Búsqueda&quot;">​</a></h3><p><strong>❔ P: ¿Puedo buscar por múltiples roles a la vez?</strong><br> ⚠️ <strong>R:</strong> El sistema no permite seleccionar múltiples roles simultáneamente. Para comparar diferentes roles, necesitará generar reportes separados.</p><p><strong>❔ P: Si no especifico fechas, ¿qué período de tiempo se muestra por defecto?</strong><br> 📅 <strong>R:</strong> Por defecto, el sistema muestra los datos de los últimos 6 meses hasta la fecha actual.</p><p><strong>❔ P: ¿Es posible buscar por monto específico?</strong><br> ⚠️ <strong>R:</strong> El reporte actual no incluye filtro por monto. Se recomienda exportar a Excel para realizar este tipo de filtrado.</p><h3 id="👁️-visualizacion-y-exportacion" tabindex="-1">👁️ Visualización y Exportación <a class="header-anchor" href="#👁️-visualizacion-y-exportacion" aria-label="Permalink to &quot;👁️ Visualización y Exportación&quot;">​</a></h3><p><strong>❔ P: ¿Existe un límite en la cantidad de registros que puede mostrar el reporte?</strong><br> 📊 <strong>R:</strong> El sistema puede manejar hasta 10,000 registros en una sola visualización. Para conjuntos de datos más grandes, se recomienda aplicar filtros más específicos.</p><p><strong>❔ P: ¿Puedo personalizar las columnas que se muestran en el reporte?</strong><br> ⚠️ <strong>R:</strong> La versión actual del reporte tiene un formato fijo. Para análisis personalizados, se recomienda exportar a Excel.</p><p><strong>❔ P: Al exportar a PDF, ¿se mantiene el formato de agrupación por empleado?</strong><br> ✅ <strong>R:</strong> Sí, la exportación a PDF conserva exactamente el mismo formato y agrupación que se ve en pantalla.</p><h3 id="🛠️-resolucion-de-problemas" tabindex="-1">🛠️ Resolución de Problemas <a class="header-anchor" href="#🛠️-resolucion-de-problemas" aria-label="Permalink to &quot;🛠️ Resolución de Problemas&quot;">​</a></h3><p><strong>❔ P: El reporte se carga muy lentamente, ¿qué puedo hacer?</strong><br> ⚡ <strong>R:</strong> Pruebe a reducir el rango de fechas o aplicar filtros adicionales para limitar la cantidad de datos procesados.</p><p><strong>❔ P: ¿Por qué algunos empleados aparecen duplicados en el reporte?</strong><br> 🔄 <strong>R:</strong> Esto puede ocurrir si el empleado está registrado con variaciones en su nombre (por ejemplo, con o sin segundo apellido). Recomendamos buscar por ID para obtener resultados precisos.</p><p><strong>❔ P: He encontrado discrepancias en los montos totales, ¿a qué se debe?</strong><br> 💰 <strong>R:</strong> Verifique si los filtros aplicados están excluyendo algunos registros relevantes. También confirme que está observando el campo &quot;Total con impuestos&quot; y no el &quot;Total sin impuestos&quot;.</p><hr><h2 id="📞-soporte" tabindex="-1">📞 <strong>Soporte</strong> <a class="header-anchor" href="#📞-soporte" aria-label="Permalink to &quot;📞 **Soporte**&quot;">​</a></h2><p>Para asistencia contactar a:<br> ✉️ <strong><a href="mailto:soporte@flowsma.com" target="_blank" rel="noreferrer">soporte@flowsma.com</a></strong><br> ☎️ +54 9 353 474-6217 <br> 📩 <a href="https://surl.li/kmiuwb" target="_blank" rel="noreferrer"><code>Ingresa al formulario</code></a></p><h3 id="tips-utiles-para-pedir-ayuda" tabindex="-1">Tips útiles para pedir ayuda: <a class="header-anchor" href="#tips-utiles-para-pedir-ayuda" aria-label="Permalink to &quot;Tips útiles para pedir ayuda:&quot;">​</a></h3><ul><li>📸 Capturas de pantalla de errores o filtros usados</li><li>📅 Especificar rangos de fecha y tipo de reporte</li><li>📥 Exportar y compartir el Excel si es posible</li></ul><hr>',71)]))}const h=a(s,[["render",l]]);export{m as __pageData,h as default};
